using System.Text;

namespace Flagstaff.Compiler;

/// <summary>
/// Generates IValueConverter implementations and the static Converters class
/// that the generated XAML references via StaticResource and x:Bind.
/// </summary>
public static class ConverterGenerator
{
    public static OutputFile GenerateBoolToVisibility(string appNamespace) =>
        new("BoolToVisibilityConverter.g.cs", $$"""
            // Auto-generated by Flagstaff — overwritten on next flagstaff compile.
            #nullable enable
            using Microsoft.UI.Xaml;
            using Microsoft.UI.Xaml.Data;

            namespace {{appNamespace}};

            public sealed class BoolToVisibilityConverter : IValueConverter
            {
                public object Convert(object value, Type targetType, object parameter, string language) =>
                    value is true ? Visibility.Visible : Visibility.Collapsed;

                public object ConvertBack(object value, Type targetType, object parameter, string language) =>
                    value is Visibility.Visible;
            }
            """);

    public static OutputFile GenerateCurrencyConverter(string appNamespace) =>
        new("CurrencyConverter.g.cs", $$"""
            // Auto-generated by Flagstaff — overwritten on next flagstaff compile.
            #nullable enable
            using Microsoft.UI.Xaml.Data;

            namespace {{appNamespace}};

            public sealed class CurrencyConverter : IValueConverter
            {
                public object Convert(object value, Type targetType, object parameter, string language) =>
                    value is decimal d ? d.ToString("C") : value?.ToString() ?? "";

                public object ConvertBack(object value, Type targetType, object parameter, string language) =>
                    throw new NotImplementedException();
            }
            """);

    public static OutputFile GeneratePercentConverter(string appNamespace) =>
        new("PercentConverter.g.cs", $$"""
            // Auto-generated by Flagstaff — overwritten on next flagstaff compile.
            #nullable enable
            using Microsoft.UI.Xaml.Data;

            namespace {{appNamespace}};

            public sealed class PercentConverter : IValueConverter
            {
                public object Convert(object value, Type targetType, object parameter, string language) =>
                    value is double d ? d.ToString("P1") : value?.ToString() ?? "";

                public object ConvertBack(object value, Type targetType, object parameter, string language) =>
                    throw new NotImplementedException();
            }
            """);

    public static OutputFile GenerateDateConverter(string appNamespace) =>
        new("DateConverter.g.cs", $$"""
            // Auto-generated by Flagstaff — overwritten on next flagstaff compile.
            #nullable enable
            using Microsoft.UI.Xaml.Data;

            namespace {{appNamespace}};

            public sealed class DateConverter : IValueConverter
            {
                public object Convert(object value, Type targetType, object parameter, string language) =>
                    value is DateTimeOffset dto ? dto.ToString("d") : value?.ToString() ?? "";

                public object ConvertBack(object value, Type targetType, object parameter, string language) =>
                    throw new NotImplementedException();
            }
            """);

    /// <summary>
    /// <c>format: number(2)</c> → <c>Converter={StaticResource NumberConverter}, ConverterParameter=F2</c>.
    /// Formats double/decimal/int (any IFormattable) with the parameter as the .NET format string ("G" without one).
    /// </summary>
    public static OutputFile GenerateNumberConverter(string appNamespace) =>
        new("NumberConverter.g.cs", $$"""
            // Auto-generated by Flagstaff — overwritten on next flagstaff compile.
            #nullable enable
            using Microsoft.UI.Xaml.Data;

            namespace {{appNamespace}};

            public sealed class NumberConverter : IValueConverter
            {
                public object Convert(object value, Type targetType, object parameter, string language)
                {
                    var format = parameter is string { Length: > 0 } p ? p : "G";
                    return value switch
                    {
                        double d => d.ToString(format),
                        decimal m => m.ToString(format),
                        int i => i.ToString(format),
                        IFormattable f => f.ToString(format, null),
                        _ => value?.ToString() ?? "",
                    };
                }

                public object ConvertBack(object value, Type targetType, object parameter, string language) =>
                    throw new NotImplementedException();
            }
            """);

    public static OutputFile GenerateConvertersClass(string appNamespace) =>
        new("Converters.g.cs", $$"""
            // Auto-generated by Flagstaff — overwritten on next flagstaff compile.
            #nullable enable
            using Microsoft.UI.Xaml;

            namespace {{appNamespace}};

            public static class Converters
            {
                public static Visibility IsPositive(int value) =>
                    value > 0 ? Visibility.Visible : Visibility.Collapsed;

                public static Visibility IsNonNegative(int value) =>
                    value >= 0 ? Visibility.Visible : Visibility.Collapsed;

                public static Visibility IsNegative(int value) =>
                    value < 0 ? Visibility.Visible : Visibility.Collapsed;

                public static Visibility IsNonPositive(int value) =>
                    value <= 0 ? Visibility.Visible : Visibility.Collapsed;

                public static Visibility IsZero(int value) =>
                    value == 0 ? Visibility.Visible : Visibility.Collapsed;

                public static Visibility IsNonZero(int value) =>
                    value != 0 ? Visibility.Visible : Visibility.Collapsed;
            }
            """);

    public static List<OutputFile> GenerateAll(string appNamespace) =>
    [
        GenerateBoolToVisibility(appNamespace),
        GenerateCurrencyConverter(appNamespace),
        GeneratePercentConverter(appNamespace),
        GenerateDateConverter(appNamespace),
        GenerateNumberConverter(appNamespace),
        GenerateConvertersClass(appNamespace),
    ];
}
